package de.maxhenkel.corpse.corelib.death;
import fixture.Game;import java.util.*;import net.minecraft.core.*;import net.minecraft.core.HolderLookup.Provider;import net.minecraft.nbt.*;import net.minecraft.world.item.ItemStack;import de.maxhenkel.corpse.corelib.item.ItemUtils;
public class Death{public UUID owner;public String name;public NonNullList<ItemStack>equipment=NonNullList.withSize(7,ItemStack.EMPTY),items=NonNullList.create();public static Death fromPlayer(Object obj){Game.Entity p=(Game.Entity)obj;Death d=new Death();d.owner=p.uuid;d.name=p.name;for(int i=0;i<7;i++)d.equipment.set(i,p.equipment.get(i).copy());return d;}public CompoundTag toNBT(Provider p,boolean all){CompoundTag t=new CompoundTag();t.putUUID("PlayerUuid",owner);t.putString("PlayerName",name);ItemUtils.saveItemList(p,t,"Equipment",equipment);return t;}public static Death fromNBT(Provider p,CompoundTag t){Death d=new Death();d.owner=t.getUUID("PlayerUuid");d.name=t.getString("PlayerName");ItemUtils.readItemList(p,t,"Equipment",d.equipment);return d;}public NonNullList<ItemStack>getEquipment(){return equipment;}public NonNullList<ItemStack>getAdditionalItems(){return items;}public UUID getPlayerUUID(){return owner;}public String getPlayerName(){return name;}public byte getModel(){return 0;}}
